using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options backed by a source-generated context that only knows about WeatherForecast.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got typed info  : {typedInfo.Type.Name}  (kind: {typedInfo.Kind})");

// 2) Probe without throwing — TryGetTypeInfo returns false when the type isn't known.
if (options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? found))
    Console.WriteLine($"TryGet(Forecast): found — {found!.Type.Name}");
else
    Console.WriteLine("TryGet(Forecast): not found");

if (options.TryGetTypeInfo(typeof(DateTime), out JsonTypeInfo? notFound))
    Console.WriteLine($"TryGet(DateTime) : found — {notFound!.Type.Name}");
else
    Console.WriteLine("TryGet(DateTime) : not found (no exception thrown)");

// -------------------------------------------------------------------
public record WeatherForecast(string City, double TempC);

[JsonSerializable(typeof(WeatherForecast))]
partial class AppJsonContext : JsonSerializerContext;

